namespace LastRail.Tests.EditMode {
 public sealed class BRouteConsumerTests {
  static BRouteBinding ActiveCompletionBinding(){var p=Pending();p["mapRevision"]=3;p["phase"]="ACTIVE";p["currentNode"]=p["pendingNode"].DeepClone();p["pendingNode"]=JValue.CreateNull();p["pendingEdgeId"]=JValue.CreateNull();return Read(Repin(p));}
  static BRouteCommand Complete(BRouteBinding b)=>BRouteCommand.FromOriginal(b,new JObject{["kind"]="COMPLETE",["eventId"]="COMPLETE_LOCAL",["expectedRevision"]=b.MapRevision,["nodeId"]="n1-0",["evidenceRef"]="LOCAL_ACCEPTED_ORIGINAL_REF"});
  static BRouteCommandResult CompleteReply(BRouteCommand cmd,bool committed)=>BRouteCommandResult.Read(committed?200:409,committed?new JObject{["version"]=BRouteBinding.Version,["committed"]=true,["receipt"]=Sample()["localAccepted"]["complete"].DeepClone()}.ToString():Sample()["defaultArrivalRefusal"].ToString(),cmd);
  [TestCase(false,false)][TestCase(false,true)][TestCase(true,false)][TestCase(true,true)]
  public async Task CompletionSurvivesViewDetachWithoutNotifyingOldOrReboundView(bool rebind,bool committed){
   var b=ActiveCompletionBinding();using(var c=new BRouteSessionController("a",b.RunId)){
    await c.RefreshAsync(()=>Task.FromResult(b));int oldCalls=0,newCalls=0;c.Bind(_=>oldCalls++);
    var cmd=Complete(b);var delayed=new TaskCompletionSource<BRouteCommandResult>();var pending=c.SendAsync(cmd,()=>delayed.Task);
    c.Unbind();if(rebind)c.Bind(_=>newCalls++);var reply=CompleteReply(cmd,committed);delayed.SetResult(reply);
    Assert.IsTrue(await pending);Assert.AreEqual(0,oldCalls);Assert.AreEqual(0,newCalls);
    var saved=c.Capture();Assert.IsTrue(JToken.DeepEquals(reply.Capture(),saved["lastResult"]));Assert.IsTrue(JToken.DeepEquals(cmd.Capture(),saved["lastCommand"]));Assert.IsFalse((bool)saved["mutationReconciliationRequired"]);
    using(var restored=BRouteSessionController.Restore(saved,BDirectAttackInput.Digest(saved),null,"a",b.RunId))Assert.IsTrue(JToken.DeepEquals(saved,restored.Capture()));
    Assert.IsTrue(await c.SendAsync(cmd,()=>Task.FromResult(reply)));Assert.IsTrue(JToken.DeepEquals(saved,c.Capture()));Assert.AreEqual(0,newCalls,"identical confirmed response must not republish");
   }
  }
  [TestCase(false)][TestCase(true)]
  public async Task CompletionCannotSurviveOwnerDisposalOrNewRouteOperation(bool dispose){
   var b=ActiveCompletionBinding();using(var c=new BRouteSessionController("a",b.RunId)){
    await c.RefreshAsync(()=>Task.FromResult(b));var cmd=Complete(b);var delayed=new TaskCompletionSource<BRouteCommandResult>();var pending=c.SendAsync(cmd,()=>delayed.Task);c.Unbind();
    if(dispose)c.Dispose();else await c.RefreshAsync(()=>Task.FromResult(b));delayed.SetResult(CompleteReply(cmd,true));Assert.IsFalse(await pending);
    if(dispose)Assert.Throws<ObjectDisposedException>(()=>c.Capture());else{Assert.AreEqual(JTokenType.Null,c.Capture()["lastResult"].Type);Assert.IsTrue((bool)c.Capture()["mutationReconciliationRequired"]);}
   }
  }
  [Test] public async Task RouteSendSupersedesPendingChildDestination(){var b=Read(Pending());using(var c=new BRouteSessionController("a",b.RunId)){await c.RefreshAsync(()=>Task.FromResult(b));var intent=new BOperationDestinationIntent("a",b.RunId,"late-select",2,"entry:n1-0");var pending=new TaskCompletionSource<BOperationDestinationReceipt>();var choose=c.ConfirmDestinationAsync(intent,()=>pending.Task);var cmd=BRouteCommand.FromOriginal(b,Arrival(b));await c.SendAsync(cmd,()=>Task.FromResult(BRouteCommandResult.Read(409,Sample()["defaultArrivalRefusal"].ToString(),cmd)));pending.SetResult(BOperationDestinationReceipt.Read(new JObject{["version"]="operation.map-destination.v1",["requestId"]="late-select",["revision"]=3,["phase"]="TRAVELLING",["pendingEdgeId"]="entry:n1-0"}.ToString(),intent));Assert.IsFalse(await choose);Assert.AreEqual(JTokenType.Null,c.Capture()["nodeSession"]["destination"].Type);}}
  [Test] public async Task MissingOriginalMotionCannotAttachToExistingNodeOnlyBinding(){var b=Read(Pending());using(var c=new BRouteSessionController("a",b.RunId)){await c.RefreshAsync(()=>Task.FromResult(b));var before=c.Capture();Assert.Throws<InvalidOperationException>(()=>c.AttachLocalTravel(null,null,null));Assert.IsTrue(JToken.DeepEquals(before,c.Capture()));Assert.IsTrue(await c.RefreshAsync(()=>Task.FromResult(b)));Assert.AreEqual(JTokenType.Null,c.Capture()["nodeSession"]["runtime"].Type);}}
  [Test] public async Task SupersededMutationCompletionRequiresReadAfterSettlement(){var b=Read(Pending());using(var c=new BRouteSessionController("a",b.RunId)){await c.RefreshAsync(()=>Task.FromResult(b));var cmd=BRouteCommand.FromOriginal(b,Arrival(b));var delayed=new TaskCompletionSource<BRouteCommandResult>();var send=c.SendAsync(cmd,()=>delayed.Task);await c.RefreshAsync(()=>Task.FromResult(b));delayed.SetResult(BRouteCommandResult.Read(200,new JObject{["version"]=BRouteBinding.Version,["committed"]=true,["receipt"]=Sample()["localAccepted"]["arrival"].DeepClone()}.ToString(),cmd));Assert.IsFalse(await send);Assert.IsTrue((bool)c.Capture()["routeRefreshRequired"]);Assert.AreEqual(JTokenType.Null,c.Capture()["lastResult"].Type);Assert.Throws<InvalidOperationException>(()=>c.Advance("stale-after-commit",10000000,500));await c.RefreshAsync(()=>Task.FromResult(Read(After())));Assert.IsFalse((bool)c.Capture()["routeRefreshRequired"]);}}
  [Test] public async Task ReadStartedBeforeMutationSettlementCannotClearFence(){var b=Read(Pending());using(var c=new BRouteSessionController("a",b.RunId)){await c.RefreshAsync(()=>Task.FromResult(b));var cmd=BRouteCommand.FromOriginal(b,Arrival(b));var mutation=new TaskCompletionSource<BRouteCommandResult>();var send=c.SendAsync(cmd,()=>mutation.Task);var delayedRead=new TaskCompletionSource<BRouteBinding>();var read=c.RefreshAsync(()=>delayedRead.Task);mutation.SetResult(BRouteCommandResult.Read(409,Sample()["defaultArrivalRefusal"].ToString(),cmd));Assert.IsFalse(await send);delayedRead.SetResult(b);Assert.IsTrue(await read);Assert.IsTrue((bool)c.Capture()["routeRefreshRequired"]);await c.RefreshAsync(()=>Task.FromResult(b));Assert.IsFalse((bool)c.Capture()["routeRefreshRequired"]);}}
  [Test] public async Task CurrentRefusalPublishesExactlySettledFence(){var b=Read(Pending());using(var c=new BRouteSessionController("a",b.RunId)){await c.RefreshAsync(()=>Task.FromResult(b));JObject shown=null;int calls=0;c.Bind(p=>{shown=p;calls++;});var cmd=BRouteCommand.FromOriginal(b,Arrival(b));await c.SendAsync(cmd,()=>Task.FromResult(BRouteCommandResult.Read(409,Sample()["defaultArrivalRefusal"].ToString(),cmd)));Assert.AreEqual(1,calls);Assert.IsTrue(JToken.DeepEquals(c.Capture(),shown),"View must receive settled state, not in-flight state");}}
  [Test] public void ActualRouteNeedsStrictOriginalBinding(){Assert.NotNull(typeof(BDirectAttackInput).Assembly.GetType("LastRail.Run.BRouteBinding"));}
  internal static JObject Sample()=>JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/QA/CommanderS1-20260922/combat-b-route-sample-20261005.json"));
  static JObject Repin(JObject p){p.Remove("packetHash");p["packetHash"]=BDirectAttackInput.Digest(p).Substring(7);return p;}
  internal static BRouteBinding Read(JObject p)=>BRouteBinding.Read(p.ToString(),(string)p["packetHash"],"a","LOCAL_B12_RUN");
  static JObject Pending()=>(JObject)Sample()["pendingBinding"].DeepClone();
  static JObject After()=>(JObject)Sample()["localAccepted"]["afterBinding"].DeepClone();
  internal static JObject Arrival(BRouteBinding b)=>new JObject{["kind"]="ARRIVE",["eventId"]="arrival",["expectedRevision"]=b.MapRevision,["edgeId"]=b.Capture()["pendingEdgeId"].DeepClone(),["evidenceRef"]="LOCAL_ACCEPTED_ORIGINAL_REF"};
  [Test] public async Task LaterRefusalCannotClearPreviouslyCommittedMapRefreshFence(){var b=Read(Pending());var cmd=BRouteCommand.FromOriginal(b,Arrival(b));var packet=new JObject{["version"]=BRouteBinding.Version,["committed"]=true,["receipt"]=Sample()["localAccepted"]["arrival"].DeepClone()};using(var c=new BRouteSessionController("a",b.RunId)){await c.RefreshAsync(()=>Task.FromResult(b));await c.SendAsync(cmd,()=>Task.FromResult(BRouteCommandResult.Read(200,packet.ToString(),cmd)));await c.SendAsync(cmd,()=>Task.FromResult(BRouteCommandResult.Read(409,Sample()["defaultArrivalRefusal"].ToString(),cmd)));Assert.IsTrue((bool)c.Capture()["routeRefreshRequired"],"Committed map revision must survive later diagnostic refusal");var p=c.Capture();using(var r=BRouteSessionController.Restore(p,BDirectAttackInput.Digest(p),null,"a",b.RunId))Assert.IsTrue((bool)r.Capture()["routeRefreshRequired"]);}}
  [Test] public void ReleaseHoldReceiptMustPreserveOriginalKnownPhase(){var p=After();p["mapRevision"]=4;p["holdIds"]=Sample()["localAccepted"]["complete"]["state"]["holdIds"].DeepClone();var b=Read(Repin(p));var command=new JObject{["kind"]="RELEASE_HOLD",["eventId"]="RELEASE_LOCAL",["expectedRevision"]=4,["holdId"]="LOCAL_REWARD_HOLD",["evidenceRef"]="LOCAL_ACCEPTED_ORIGINAL_REF"};var c=BRouteCommand.FromOriginal(b,command);var receipt=new JObject{["version"]=BRouteBinding.Version,["committed"]=true,["receipt"]=Sample()["localAccepted"]["release"].DeepClone()};Assert.IsTrue(BRouteCommandResult.Read(200,receipt.ToString(),c).Committed);receipt["receipt"]["state"]["phase"]="ARBITRARY";Assert.Throws<ArgumentException>(()=>BRouteCommandResult.Read(200,receipt.ToString(),c));}
  [Test] public void ExactOriginalSelectedNodeAndNativeContextAreBoundWithoutReroll(){var b=Read(Pending());Assert.AreEqual("n1-0",b.NativeNode.NodeId);Assert.AreNotEqual(b.RunId,b.NativeNode.NativeContextId);Assert.IsTrue(JToken.DeepEquals(b.Capture(),Pending()));Assert.IsNull(Read((JObject)Sample()["initialBinding"]).NativeNode);Assert.IsFalse(b.CanStart);}
  [TestCase("accountId")][TestCase("runId")][TestCase("nativeContextId")][TestCase("nodeSourceStatus")][TestCase("startSnapshotHash")]
  public void IdentityPinAndOriginalNodeConflictCannotBePromoted(string field){var p=Pending();p[field]=field=="nativeContextId"?p["runId"].DeepClone():new JValue("wrong");Repin(p);Assert.Throws<ArgumentException>(()=>Read(p));}
  [Test] public void UnknownLaterNodeAndLegacyPinsRemainExplicitNull(){var p=Pending();p["nativeNodeSource"]=JValue.CreateNull();p["nodeSourceStatus"]="ORIGINAL_NODE_REFS_ONLY";Assert.IsNull(Read(Repin(p)).NativeNode);p["nativeContextId"]=JValue.CreateNull();p["departurePinHash"]=JValue.CreateNull();p["originalNativeOrigin"]=JValue.CreateNull();var b=Read(Repin(p));Assert.IsNull(b.NativeNode);Assert.AreEqual(JTokenType.Null,b.Capture()["nativeContextId"].Type);}
  [Test] public void OriginalMapWaveCommitsDifferFromDiagnosticAndDefaultSourceRefusal(){var b=Read(Pending());var c=BRouteCommand.FromOriginal(b,Arrival(b));var success=new JObject{["version"]=BRouteBinding.Version,["committed"]=true,["receipt"]=Sample()["localAccepted"]["arrival"].DeepClone()};var r=BRouteCommandResult.Read(200,success.ToString(),c);Assert.IsTrue(r.Committed);Assert.IsFalse(r.CanAuthorizeEquipment);var refusal=BRouteCommandResult.Read(409,Sample()["defaultArrivalRefusal"].ToString(),c);Assert.IsFalse(refusal.Committed);Assert.That(((JArray)refusal.Capture()["missingSources"]).Count,Is.GreaterThan(0));success["committed"]=false;Assert.Throws<ArgumentException>(()=>BRouteCommandResult.Read(200,success.ToString(),c));Assert.Throws<ArgumentException>(()=>BRouteCommandResult.Read(200,"{\"accepted\":false}",c));Assert.Throws<ArgumentException>(()=>BRouteCommand.FromOriginal(b,new JObject{["kind"]="CONFIRM",["eventId"]="wrong",["evidenceRef"]="LOCAL"}));}
  [Test] public async Task OriginalPacketBindsExistingNodeOwnerAndRestoresController(){var b=Read(Pending());using(var c=new BRouteSessionController("a",b.RunId)){Assert.IsTrue(await c.RefreshAsync(()=>Task.FromResult(b)));var p=c.Capture();Assert.IsTrue(JToken.DeepEquals(b.NativeNode.Capture(),p["nodeSession"]["node"]));Assert.AreEqual(JTokenType.Null,p["nodeSession"]["runtime"].Type);Assert.Throws<InvalidOperationException>(()=>c.Advance("no-speed",10000000,500));using(var restored=BRouteSessionController.Restore(p,BDirectAttackInput.Digest(p),null,"a",b.RunId))Assert.IsTrue(JToken.DeepEquals(p,restored.Capture()));var forged=(JObject)p.DeepClone();forged["nodeSession"]["node"]["sourceHash"]="wrong";Assert.Throws<ArgumentException>(()=>BRouteSessionController.Restore(forged,BDirectAttackInput.Digest(forged),null,"a",b.RunId));Assert.IsFalse((bool)c.DescribeRuntimeSources()["acceptedRouteEvidenceSupported"]);}}
  [Test] public async Task ReceiptPersistsOriginalBodyAndHistoricalBindingSeparatelyFromRefresh(){var b=Read(Pending());var cmd=BRouteCommand.FromOriginal(b,Arrival(b));var packet=new JObject{["version"]=BRouteBinding.Version,["committed"]=true,["receipt"]=Sample()["localAccepted"]["arrival"].DeepClone()};using(var c=new BRouteSessionController("a",b.RunId)){await c.RefreshAsync(()=>Task.FromResult(b));await c.SendAsync(cmd,()=>Task.FromResult(BRouteCommandResult.Read(200,packet.ToString(),cmd)));Assert.IsTrue((bool)c.Capture()["routeRefreshRequired"]);await c.RefreshAsync(()=>Task.FromResult(Read(After())));Assert.IsFalse((bool)c.Capture()["routeRefreshRequired"]);var p=c.Capture();using(var r=BRouteSessionController.Restore(p,BDirectAttackInput.Digest(p),null,"a",b.RunId))Assert.IsTrue(JToken.DeepEquals(p,r.Capture()));Assert.IsTrue(JToken.DeepEquals(cmd.Capture(),c.Capture()["lastCommand"]));}}
  [Test] public async Task LateRouteAndMutationCannotPublishAfterUnbindDisposeOrNewRequest(){var b=Read(Pending());using(var c=new BRouteSessionController("a",b.RunId)){int calls=0;c.Bind(_=>calls++);var pending=new TaskCompletionSource<BRouteBinding>();var late=c.RefreshAsync(()=>pending.Task);c.Unbind();pending.SetResult(b);Assert.IsFalse(await late);Assert.AreEqual(0,calls);await c.RefreshAsync(()=>Task.FromResult(b));var cmd=BRouteCommand.FromOriginal(b,Arrival(b));var result=new TaskCompletionSource<BRouteCommandResult>();var mutation=c.SendAsync(cmd,()=>result.Task);c.Dispose();result.SetResult(BRouteCommandResult.Read(409,Sample()["defaultArrivalRefusal"].ToString(),cmd));Assert.IsFalse(await mutation);Assert.Throws<ObjectDisposedException>(()=>c.Capture());}}
  [Test] public async Task SourceHashRevisionAndImmutableDepartureChangesFailWithoutReplacement(){var b=Read(Pending());using(var c=new BRouteSessionController("a",b.RunId)){await c.RefreshAsync(()=>Task.FromResult(b));var before=c.Capture();var p=After();p["startSnapshotHash"]=new string('f',64);Repin(p);Assert.ThrowsAsync<ArgumentException>(async()=>await c.RefreshAsync(()=>Task.FromResult(Read(p))));Assert.IsTrue(JToken.DeepEquals(before,c.Capture()));Assert.Throws<ArgumentException>(()=>BRouteBinding.Read(Pending().ToString(),new string('0',64),"a",b.RunId));}}
  [Test] public async Task OriginalBearerRouteWireHasGetOnlyIfMatchAndImmutableMutationEnvelope(){var b=Read(Pending());var wire=new RunRiskBindingTests.Wire{Reply=q=>Task.FromResult(RunApiHttpResponse.Success(200,Pending().ToString(),new[]{new RunApiHttpHeader("ETag",b.Hash)}))};var client=new BRouteHttpClient(new GameApiAuthenticatedHttpTransport(wire));var token=new GameApiAccessToken("lst1.fixture");await client.ReadAsync("a",b.RunId,token,b.Hash);Assert.AreEqual("GET",wire.Last.Method);Assert.IsNull(wire.Last.BodyJson);Assert.IsTrue(wire.Last.Headers.Any(h=>h.Name=="If-Match"&&h.Value==b.Hash));var cmd=BRouteCommand.FromOriginal(b,Arrival(b));wire.Reply=q=>Task.FromResult(RunApiHttpResponse.Success(409,Sample()["defaultArrivalRefusal"].ToString()));var result=await client.SendAsync(cmd,token);Assert.IsFalse(result.Committed);Assert.IsTrue(JToken.DeepEquals(cmd.Capture(),JObject.Parse(wire.Last.BodyJson)));Assert.IsFalse(wire.Last.Headers.Any(h=>h.Name=="If-Match"));Assert.IsTrue(wire.Last.Headers.Any(h=>h.Name=="Idempotency-Key"&&h.Value==cmd.EventId));Assert.IsTrue(wire.Last.Headers.Any(h=>h.Name=="Authorization"));}
 }
